    base = str(name).split(',')[0].strip()
    if base not in categories:
        categories[base] = 0
    categories[base] += 1

print('Anno name base categories:')
for k in sorted(categories.keys()):
    print(f'  {k}: {categories[k]} variants')
" 2>&1

